# PS5 plain-text printing for the checker and the financial report. Students do not edit this file.
#
# The file reads from top to bottom:
#   1. Text and headings
#   2. Tables

# The widest line that the checker and the report print (display columns).
const _TERMINAL_WIDTH = 78;

# --- 1. Text and headings -----------------------------------------------------------------------

"""
    print_terminal_text(text; prefix="", continuation=prefix, width=78) -> Nothing

Print text with word wrapping and optional hanging indentation. Explicit line breaks stay in place,
and a word longer than the line is split, so that each printed line fits `width` display columns.
The function does not add color or terminal controls.

### Arguments

- `text`: The text to print.
- `prefix`: The characters in front of the first line of each paragraph.
- `continuation`: The characters in front of each later line of a paragraph.
- `width`: The widest printed line (display columns).
"""
function print_terminal_text(text::AbstractString; prefix::String="",
    continuation::String=prefix, width::Int=_TERMINAL_WIDTH)::Nothing

    # main loop: each explicit line break starts a new paragraph -
    for paragraph in split(text, '\n')
        line = prefix; # the line being built
        has_word = false; # true once the line holds a word

        # one word at a time -
        for word in split(paragraph)

            # Start a new line when the word and its space do not fit -
            if has_word && textwidth(line) + 1 + textwidth(word) > width
                println(rstrip(line));
                line = continuation;
                has_word = false;
            end

            # Separate this word from the previous word -
            if has_word
                line *= " ";
            end

            # Add the word one character at a time, so that a long word can be split -
            for character in word
                if textwidth(line) + textwidth(character) > width
                    println(rstrip(line));
                    line = continuation;
                end
                line *= string(character);
            end
            has_word = true;
        end

        # Print the last line of the paragraph -
        println(rstrip(line));
    end
    return nothing;
end

"""
    print_terminal_detail(text; prefix="  ", width=78) -> Nothing

Print diagnostic text while preserving spaces and line breaks, including Julia's source snippets and
error pointers. Long lines wrap at spaces when possible. A long word is split only if the word
cannot fit within the display width.

### Arguments

- `text`: The diagnostic text to print.
- `prefix`: The characters in front of every printed line.
- `width`: The widest printed line (display columns).
"""
function print_terminal_detail(text::AbstractString; prefix::String="  ", width::Int=_TERMINAL_WIDTH)::Nothing

    # main loop: one line of the original text at a time -
    for original in split(replace(text, '\t' => "    "), '\n')
        characters = collect(original);

        # An empty line stays empty -
        if isempty(characters)
            println();
        end

        # Print the line in pieces that fit -
        start = 1;
        while start <= length(characters)

            # Find the last character that fits on this printed line -
            stop = start - 1;
            occupied = textwidth(prefix);
            while stop < length(characters) && occupied + textwidth(characters[stop+1]) <= width
                stop += 1;
                occupied += textwidth(characters[stop]);
            end

            # When text remains, break at the last space that has text before it -
            if stop < length(characters)
                gap = findlast(isspace, characters[start:stop]);
                if gap !== nothing && any(c -> !isspace(c), characters[start:start+gap-2])
                    finish = start + gap - 2;
                    println(rstrip(prefix * join(characters[start:finish])));
                    start = finish + 2;
                    continue;
                end
            end

            # Otherwise print everything that fits -
            println(rstrip(prefix * join(characters[start:stop])));
            start = stop + 1;
        end
    end
    return nothing;
end

"""
    print_terminal_section(title; major=false) -> Nothing

Print a separated heading. A major section has a rule of `=` above and below its title, across the
full width. A smaller section has a rule of `-` below its title, as long as the title.
"""
function print_terminal_section(title::String; major::Bool=false)::Nothing

    # A blank line, then the rule above a major heading -
    println();
    if major
        println(repeat("=", _TERMINAL_WIDTH));
    end

    # The title, then the rule below it -
    print_terminal_text(title);
    if major
        println(repeat("=", _TERMINAL_WIDTH));
    else
        println(repeat("-", min(textwidth(title), _TERMINAL_WIDTH)));
    end
    return nothing;
end

# --- 2. Tables ----------------------------------------------------------------------------------

"""
    _print_terminal_labeled_rows(headers, rows) -> Nothing

Print each row of a table as labeled values, one per line, for a table too wide for the terminal.
"""
function _print_terminal_labeled_rows(headers::Vector{String}, rows::Vector{Vector{String}})::Nothing
    for (index, row) in enumerate(rows)

        # A blank line separates one row from the next -
        if index > 1
            println();
        end
        for (header, value) in zip(headers, row)
            print_terminal_text("$(header): $(value)"; prefix="  ");
        end
    end
    return nothing;
end

"""
    _print_terminal_row(cells, widths, right_columns) -> Nothing

Print one row of a table, with each cell padded to the width of its column.

### Arguments

- `cells`: The text of each cell.
- `widths`: The width of each column (display columns).
- `right_columns`: The positions of the right-aligned columns.
"""
function _print_terminal_row(cells::Vector{String}, widths::Vector{Int}, right_columns::Vector{Int})::Nothing

    # Pad each cell to the width of its column -
    padded = String[];
    for j in eachindex(cells)
        if j in right_columns
            push!(padded, lpad(cells[j], widths[j]));
        else
            push!(padded, rpad(cells[j], widths[j]));
        end
    end

    # Join the cells, and drop the spaces at the end of the line -
    println(rstrip(join(padded, " | ")));
    return nothing;
end

"""
    print_terminal_table(headers, rows; right_columns=Int[]) -> Nothing

Print a table of strings with aligned columns and a rule beneath its header. Columns listed in
`right_columns` are right aligned. When the table would be wider than the terminal, print each row
as labeled values instead.
"""
function print_terminal_table(headers::Vector{String}, rows::Vector{Vector{String}};
    right_columns::Vector{Int}=Int[])::Nothing

    # The width of each column is its widest cell -
    widths = Int[];
    for j in eachindex(headers)
        widest = textwidth(headers[j]);
        for row in rows
            widest = max(widest, textwidth(row[j]));
        end
        push!(widths, widest);
    end

    # A table too wide for the terminal prints as labeled values; three characters separate two columns -
    if sum(widths) + 3 * (length(headers) - 1) > _TERMINAL_WIDTH
        _print_terminal_labeled_rows(headers, rows);
        return nothing;
    end

    # The header, its rule, and then one line per row -
    _print_terminal_row(headers, widths, right_columns);
    println(join([repeat("-", width) for width in widths], "-+-"));
    for row in rows
        _print_terminal_row(row, widths, right_columns);
    end
    return nothing;
end
